export interface Option {
  id: string; // 'A', 'B', 'C', etc.
  label: string;
  description?: string;
}

export interface Question {
  id: string;
  title: string;
  text?: string;
  options: Option[];
}

export interface Recommendation {
  name: string;
  why: string;
  link: string;
  image_url?: string;
}

export interface ContactInfo {
  name: string;
  email: string;
  phone: string;
  privacyAccepted: boolean;
}

export type QuizState = {
  stepIndex: number; // 0=Intro, 1=Screen2, etc.
  answers: Record<string, string>; // questionId -> optionId (A, B, C)
  contact: ContactInfo;
  isSubmitting: boolean;
  results: Recommendation[] | null;
  error: string | null;
  hasFinished: boolean;
};

// Define the steps structure for navigation logic
export enum StepType {
  INTRO = 'INTRO',
  QUESTIONS = 'QUESTIONS',
  CONTACT = 'CONTACT',
  RESULTS = 'RESULTS'
}

export interface StepConfig {
  id: string;
  type: StepType;
  title?: string;
  questions?: Question[];
  youtubeId?: string; // Optional specific video per step
  extraContent?: {
    title: string;
    text: string;
    options: Option[];
    id: string;
  };
