import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'outline' | 'ghost';
  fullWidth?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  fullWidth = false, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "py-3 px-8 rounded-full font-medium transition-all duration-300 transform active:scale-95 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-50 disabled:cursor-not-allowed text-sm tracking-wide uppercase";

  const variants = {
    primary: "bg-gray-900 text-white hover:bg-gray-800 shadow-lg hover:shadow-xl border border-transparent",
    outline: "bg-transparent text-gray-900 border border-gray-900 hover:bg-gray-50",
    ghost: "bg-transparent text-gray-600 hover:text-gray-900 hover:bg-gray-100"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

import React from 'react';

interface OptionCardProps {
  id: string; // A, B, C
  label: string;
  description?: string;
  selected: boolean;
  onClick: () => void;
}

export const OptionCard: React.FC<OptionCardProps> = ({ id, label, description, selected, onClick }) => {
  return (
    <div 
      onClick={onClick}
      className={`
        cursor-pointer group flex items-start gap-4 p-4 rounded-xl border transition-all duration-200
        ${selected 
          ? 'bg-gray-900 border-gray-900 text-white shadow-md transform scale-[1.01]' 
          : 'bg-white border-gray-200 text-gray-700 hover:border-gray-400 hover:shadow-sm'
        }
      `}
      role="radio"
      aria-checked={selected}
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onClick();
        }
      }}
    >
      <div className={`
        flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm border
        ${selected
          ? 'bg-white text-gray-900 border-white'
          : 'bg-gray-100 text-gray-500 border-gray-200 group-hover:border-gray-400'
        }
      `}>
        {id}
      </div>
      <div className="flex-1">
        <div className={`font-semibold text-lg leading-tight ${selected ? 'text-white' : 'text-gray-900'}`}>
          {label}
        </div>
        {description && (
          <div className={`mt-1 text-sm leading-relaxed ${selected ? 'text-gray-300' : 'text-gray-500'}`}>
            {description}
          </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';

interface ProgressBarProps {
  currentStep: number;
  totalSteps: number;
}

export const ProgressBar: React.FC<ProgressBarProps> = ({ currentStep, totalSteps }) => {
  // We offset by 1 because Intro (index 0) is not "Step 1" usually in UI, 
  // but let's follow the prompt which implies progress during the questions.
  // Step 1 (Vibe) is index 1.

  if (currentStep === 0) return null; // No bar on intro

  const progress = Math.min(100, (currentStep / totalSteps) * 100);

  return (
    <div className="w-full fixed top-0 left-0 z-50">
      <div className="h-1.5 w-full bg-gray-200">
        <div 
          className="h-full bg-gray-900 transition-all duration-500 ease-out"
          style={{ width: `${progress}%` }}
        />
      </div>
      <div className="absolute top-4 right-4 md:right-8 bg-white/80 backdrop-blur-sm px-3 py-1 rounded-full text-xs font-medium text-gray-600 border border-gray-200 shadow-sm">
        Paso {currentStep} de {totalSteps}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { STEPS, WEBHOOK_URL, PRIVACY_URL } from './constants';
import { QuizState, ContactInfo, Recommendation, StepType } from './types';
import { Button } from './components/Button';
import { OptionCard } from './components/OptionCard';
import { ProgressBar } from './components/ProgressBar';
import { ArrowLeft, Check, AlertCircle } from 'lucide-react';

const STORAGE_KEY = 'maldives_quiz_state';

// Generate a simple session ID
const generateSessionId = () => {
  return typeof crypto !== 'undefined' && crypto.randomUUID 
    ? crypto.randomUUID() 
    : Math.random().toString(36).substring(2, 15);
};

// Initial State
const initialState: QuizState = {
  stepIndex: 0,
  answers: {},
  contact: { name: '', email: '', phone: '', privacyAccepted: false },
  isSubmitting: false,
  results: null,
  error: null,
  hasFinished: false
};

export default function App() {
  const [state, setState] = useState<QuizState>(initialState);
  const [isLoading, setIsLoading] = useState(true);
  const sessionIdRef = useRef<string>(generateSessionId());
  const utmRef = useRef<Record<string, string>>({});

  // Load state and captured UTMs on mount
  useEffect(() => {
    // Capture UTMs
    const params = new URLSearchParams(window.location.search);
    const utms: Record<string, string> = {};
    ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term', 'gclid', 'fbclid'].forEach(key => {
      if (params.has(key)) utms[key] = params.get(key) || '';
    });
    utmRef.current = utms;

    // Load from LocalStorage
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        // Ensure we don't start on a finished state if they refresh
        if (parsed.hasFinished) {
            // Keep results if finished
             setState(parsed);
        } else {
            setState(prev => ({ ...prev, ...parsed, isSubmitting: false, error: null }));
        }
      } catch (e) {
        console.error("Failed to load state", e);
      }
    }
    setIsLoading(false);
  }, []);

  // Persist state
  useEffect(() => {
    if (!isLoading) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    }
  }, [state, isLoading]);

  const currentStepConfig = STEPS[state.stepIndex];

  // Helper to get total visible steps (approximate for UI)
  const totalSteps = STEPS.length - 1; // Excluding Intro

  // Scroll to top on step change
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [state.stepIndex]);

  const handleOptionSelect = (questionId: string, optionId: string) => {
    setState(prev => ({
      ...prev,
      answers: { ...prev.answers, [questionId]: optionId }
    }));
  };

  const handleNext = () => {
    // Validation
    if (currentStepConfig.type === StepType.QUESTIONS && currentStepConfig.questions) {
      const missing = currentStepConfig.questions.some(q => !state.answers[q.id]);
      if (missing) {
        alert("Por favor, responde a todas las preguntas para continuar.");
        return;
      }
    }

    // Conditional Logic for Step 3 (Marine) -> Step 3 Extra (Q4.1)
    if (currentStepConfig.id === 'screen-3-marine') {
      const q4Answer = state.answers['q4'];
      // If Q4 answer is NOT 'B' (Yes, priority), skip the next step (which is the conditional one)
      if (q4Answer !== 'B') {
        setState(prev => ({ ...prev, stepIndex: prev.stepIndex + 2 })); // Skip index 3 (conditional)
        return;
      }
    }

    setState(prev => ({ ...prev, stepIndex: prev.stepIndex + 1 }));
  };

  const handleBack = () => {
    if (state.stepIndex === 0) return;

    // Reverse Conditional Logic
    // If we are at 'screen-4-food' (index 4 in list), and we came from 'screen-3-marine' (index 2) because we skipped index 3...
    // We need to check if we should go back 1 or 2 steps.
    const currentId = currentStepConfig.id;

    // If current is the one AFTER conditional, check if we skipped conditional
    if (currentId === 'screen-4-food') {
         const q4Answer = state.answers['q4'];
         if (q4Answer !== 'B') {
             setState(prev => ({ ...prev, stepIndex: prev.stepIndex - 2 }));
             return;
         }
    }

    setState(prev => ({ ...prev, stepIndex: prev.stepIndex - 1 }));
  };

  const handleContactChange = (field: keyof ContactInfo, value: string | boolean) => {
    setState(prev => ({
      ...prev,
      contact: { ...prev.contact, [field]: value }
    }));
  };

  const handleSubmit = async () => {
    // Validation
    if (!state.contact.name || !state.contact.email || !state.contact.phone || !state.contact.privacyAccepted) {
      alert("Por favor, completa todos los campos obligatorios.");
      return;
    }

    setState(prev => ({ ...prev, isSubmitting: true, error: null }));

    const payload = {
      session_id: sessionIdRef.current,
      timestamp: new Date().toISOString(),
      ...utmRef.current,
      answers: state.answers,
      contact: state.contact
    };

    try {
      // Simulation of API call for demo if URL is placeholder
      let responseData: { recommendations?: Recommendation[] } = {};

      if (WEBHOOK_URL.includes("example.com")) {
        await new Promise(resolve => setTimeout(resolve, 2000)); // Fake network delay
        // Mock Response
        responseData = {
           recommendations: [
             { name: "Resort Lux South Ari", why: "Perfecto para avistamiento de tiburón ballena y ambiente vibrante.", link: "#", image_url: "https://picsum.photos/400/300?random=1" },
             { name: "Six Senses Laamu", why: "Lujo sostenible, privacidad absoluta y house reef increíble.", link: "#", image_url: "https://picsum.photos/400/300?random=2" },
             { name: "Baros Maldives", why: "El equilibrio clásico: elegancia, snorkel top y cercanía a Malé.", link: "#", image_url: "https://picsum.photos/400/300?random=3" }
           ]
        };
      } else {
          const res = await fetch(WEBHOOK_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });
          if (!res.ok) throw new Error('Error en el servidor');
          responseData = await res.json();
      }

      setState(prev => ({ 
        ...prev, 
        isSubmitting: false, 
        hasFinished: true,
        results: responseData.recommendations || null 
      }));

    } catch (err) {
      console.error(err);
      setState(prev => ({ 
        ...prev, 
        isSubmitting: false, 
        error: "Hubo un error al enviar tus respuestas. Por favor, inténtalo de nuevo." 
      }));
    }
  };

  // ---------------- RENDERERS ----------------

  if (isLoading) return null;

  // RESULTS SCREEN
  if (state.hasFinished) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-6 max-w-4xl mx-auto animate-fade-in">
        <h2 className="font-serif text-3xl md:text-4xl text-center mb-6">
            {state.results ? "Vuestros 3 resorts ideales" : "¡Gracias!"}
        </h2>

        {state.results ? (
            <div className="grid md:grid-cols-3 gap-6 w-full">
                {state.results.map((res, idx) => (
                    <div key={idx} className="bg-white rounded-xl shadow-lg overflow-hidden border border-gray-100 flex flex-col">
                        <div className="h-48 bg-gray-200 w-full relative">
                           {res.image_url ? <img src={res.image_url} alt={res.name} className="w-full h-full object-cover" /> : <div className="flex items-center justify-center h-full text-gray-400">Sin imagen</div>}
                        </div>
                        <div className="p-6 flex-1 flex flex-col">
                            <h3 className="font-serif text-xl font-bold mb-2">{res.name}</h3>
                            <p className="text-gray-600 text-sm mb-4 flex-1">{res.why}</p>
                            <a href={res.link} target="_blank" rel="noopener noreferrer" className="block text-center bg-gray-900 text-white py-2 rounded-lg text-sm uppercase tracking-wider hover:bg-gray-800 transition">
                                Ver Resort
                            </a>
                        </div>
                    </div>
                ))}
            </div>
        ) : (
            <div className="text-center max-w-lg bg-white p-8 rounded-xl shadow-sm border">
                <p className="text-lg text-gray-700 mb-4">
                    Hemos recibido tus respuestas correctamente.
                </p>
                <p className="text-gray-600">
                    Te escribiremos por WhatsApp en breve con tu selección personalizada.
                </p>
            </div>
        )}
      </div>
    );
  }

  // LOADING SCREEN (Submitting)
  if (state.isSubmitting) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-6">
