import React, { useState, useEffect, useRef } from 'react';
import { STEPS, WEBHOOK_URL, PRIVACY_URL } from './constants';
import { QuizState, ContactInfo, Recommendation, StepType } from './types';
import { Button } from './components/Button';
import { OptionCard } from './components/OptionCard';
import { ProgressBar } from './components/ProgressBar';
import { ArrowLeft, Check, AlertCircle } from 'lucide-react';

const STORAGE_KEY = 'maldives_quiz_state';

// Generate a simple session ID
const generateSessionId = () => {
  return typeof crypto !== 'undefined' && crypto.randomUUID 
    ? crypto.randomUUID() 
    : Math.random().toString(36).substring(2, 15);
};

// Initial State
const initialState: QuizState = {
  stepIndex: 0,
  answers: {},
  contact: { name: '', email: '', phone: '', privacyAccepted: false },
  isSubmitting: false,
  results: null,
  error: null,
  hasFinished: false
};

export default function App() {
  const [state, setState] = useState<QuizState>(initialState);
  const [isLoading, setIsLoading] = useState(true);
  const [validationError, setValidationError] = useState<string | null>(null);
  const sessionIdRef = useRef<string>(generateSessionId());
  const utmRef = useRef<Record<string, string>>({});

  // Load state and captured UTMs on mount
  useEffect(() => {
    // Capture UTMs
    const params = new URLSearchParams(window.location.search);
    const utms: Record<string, string> = {};
    ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term', 'gclid', 'fbclid'].forEach(key => {
      if (params.has(key)) utms[key] = params.get(key) || '';
    });
    utmRef.current = utms;

    // Load from LocalStorage
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        // Ensure we don't start on a finished state if they refresh
        if (parsed.hasFinished) {
            // Keep results if finished
             setState(parsed);
        } else {
            setState(prev => ({ ...prev, ...parsed, isSubmitting: false, error: null }));
        }
      } catch (e) {
        console.error("Failed to load state", e);
      }
    }
    setIsLoading(false);
  }, []);

  // Persist state
  useEffect(() => {
    if (!isLoading) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    }
  }, [state, isLoading]);

  const currentStepConfig = STEPS[state.stepIndex];

  // Helper to get total visible steps (approximate for UI)
  const totalSteps = STEPS.length - 1; // Excluding Intro

  // Scroll to top on step change
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [state.stepIndex]);

  const handleOptionSelect = (questionId: string, optionId: string) => {
    setValidationError(null); // Clear validation error on interaction
    setState(prev => ({
      ...prev,
      answers: { ...prev.answers, [questionId]: optionId }
    }));
  };

  const handleNext = () => {
    setValidationError(null);

    // Validation
    if (currentStepConfig.type === StepType.QUESTIONS && currentStepConfig.questions) {
      const missing = currentStepConfig.questions.some(q => !state.answers[q.id]);
      if (missing) {
        setValidationError("Por favor, selecciona una opción para todas las preguntas antes de continuar.");
        return;
      }
    }

    // Conditional Logic for Step 3 (Marine) -> Step 3 Extra (Q4.1)
    if (currentStepConfig.id === 'screen-3-marine') {
      const q4Answer = state.answers['q4'];
      // If Q4 answer is NOT 'B' (Yes, priority), skip the next step (which is the conditional one)
      // Note: 'B' is the ID for "Sí, es prioridad"
      if (q4Answer !== 'B') {
        setState(prev => ({ ...prev, stepIndex: prev.stepIndex + 2 })); // Skip index 3 (conditional)
        return;
      }
    }

    setState(prev => ({ ...prev, stepIndex: prev.stepIndex + 1 }));
  };

  const handleBack = () => {
    if (state.stepIndex === 0) return;

    // Reverse Conditional Logic
    const currentId = currentStepConfig.id;

    // If current is the one AFTER conditional (Food), check if we came from Marine (skipping conditional)
    if (currentId === 'screen-4-food') {
         const q4Answer = state.answers['q4'];
         // If we didn't pick B, we skipped the conditional step, so go back 2
         if (q4Answer !== 'B') {
             setState(prev => ({ ...prev, stepIndex: prev.stepIndex - 2 }));
             return;
         }
    }

    setState(prev => ({ ...prev, stepIndex: prev.stepIndex - 1 }));
  };

  const handleContactChange = (field: keyof ContactInfo, value: string | boolean) => {
    setState(prev => ({
      ...prev,
      contact: { ...prev.contact, [field]: value }
    }));
  };

  const handleSubmit = async () => {
    // Validation
    if (!state.contact.name || !state.contact.email || !state.contact.phone || !state.contact.privacyAccepted) {
      setValidationError("Por favor, completa todos los campos obligatorios y acepta la política de privacidad.");
      return;
    }

    setState(prev => ({ ...prev, isSubmitting: true, error: null }));

    const payload = {
      session_id: sessionIdRef.current,
      timestamp: new Date().toISOString(),
      ...utmRef.current,
      answers: state.answers,
      contact: state.contact
    };

    try {
      // Simulation of API call for demo if URL is placeholder
      let responseData: { recommendations?: Recommendation[] } = {};

      if (WEBHOOK_URL.includes("example.com")) {
        await new Promise(resolve => setTimeout(resolve, 2000)); // Fake network delay
        // Mock Response
        responseData = {
           recommendations: [
             { name: "Resort Lux South Ari", why: "Perfecto para avistamiento de tiburón ballena y ambiente vibrante.", link: "#", image_url: "https://picsum.photos/400/300?random=1" },
             { name: "Six Senses Laamu", why: "Lujo sostenible, privacidad absoluta y house reef increíble.", link: "#", image_url: "https://picsum.photos/400/300?random=2" },
             { name: "Baros Maldives", why: "El equilibrio clásico: elegancia, snorkel top y cercanía a Malé.", link: "#", image_url: "https://picsum.photos/400/300?random=3" }
           ]
        };
      } else {
          const res = await fetch(WEBHOOK_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });
          if (!res.ok) throw new Error('Error en el servidor');
          responseData = await res.json();
      }

      setState(prev => ({ 
        ...prev, 
        isSubmitting: false, 
        hasFinished: true,
        results: responseData.recommendations || null 
      }));

    } catch (err) {
      console.error(err);
      setState(prev => ({ 
        ...prev, 
        isSubmitting: false, 
        error: "Hubo un error al enviar tus respuestas. Por favor, inténtalo de nuevo." 
      }));
    }
  };

  // ---------------- RENDERERS ----------------

  if (isLoading) return null;

  // RESULTS SCREEN
  if (state.hasFinished) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-6 max-w-4xl mx-auto animate-fade-in">
