              <div className="space-y-2">
                <h3 className="font-serif text-2xl font-medium text-gray-900">{q.title}</h3>
                {q.text && <p className="text-gray-600 whitespace-pre-line leading-relaxed">{q.text}</p>}
                {/* Specific link for 4.1 */}
                {q.id === 'q4.1' && (
                     <span className="text-gray-500 underline text-sm cursor-not-allowed">Ver ejemplos de Isla local y Resort</span>
                )}
              </div>

              <div className="grid gap-3">
                {q.options.map((opt) => (
                  <OptionCard
                    key={opt.id}
                    id={opt.id}
                    label={opt.label}
                    description={opt.description}
                    selected={state.answers[q.id] === opt.id}
                    onClick={() => handleOptionSelect(q.id, opt.id)}
                  />
                ))}
              </div>
            </div>
          ))}

          {/* CONTACT FORM RENDERER */}
          {currentStepConfig.type === StepType.CONTACT && (
            <div className="space-y-8">
